WITH with_prev AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_reading_ts FROM device_readings), with_gaps AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM with_prev), sessions_device_readings AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT session_no, SIZE(COLLECT_SET(device_code)) AS num_device_codes, STDDEV_SAMP(pressure) AS pressure_stddev, MIN(reading_ts) AS first_reading_ts FROM sessions_device_readings GROUP BY 1 ORDER BY pressure_stddev DESC
